import math

def is_power_of_5(n):
    if n <= 0:
        return False
    while n % 5 == 0:
        n //= 5
    return n == 1

solutions = []
for n in range(3, 21):
    x = (2**n) - 3
    if is_power_of_5(x):
        solutions.append(n)
        print(f"n = {n}: 2^{n} - 3 = {x} (is a power of 5)")

if not solutions:
    print("No solutions found in the range 3 <= n <= 20.")
else:
    print(f"\nSolutions found: {solutions}")

import math

def is_power_of_five(n):
    if n <= 0:
        return False
    while n > 1:
        if n % 5 != 0:
            return False
        n //= 5
    return n == 1

# Compute 2^47 - 3
N = 2**47 - 3

print(f"Value of 2^47 - 3: {N}")
print(f"Is {N} a power of 5? {is_power_of_five(N)}")
